  7→}
  8→
  9→/** Valid JSON Schema type values */
 10→const VALID_TYPES = new Set(['string', 'number', 'integer', 'boolean', 'object', 'array', 'null']);
 11→
 12→/**
 13→ * Keywords that Claude's API does not support in tool input_schema.
 14→ * These get stripped recursively from any schema before returning to clients.
 15→ */
 16→const UNSUPPORTED_KEYWORDS = new Set([
 17→  // Numeric constraints
 18→  'minimum',
 19→  'maximum',
 20→  'exclusiveMinimum',
 21→  'exclusiveMaximum',
 22→  'multipleOf',
 23→  // String constraints
 24→  'minLength',
 25→  'maxLength',
 26→  // Array constraints
 27→  'maxItems',
 28→  'uniqueItems',
 29→  // Advanced schema features
 30→  'patternProperties',
 31→  'if',
 32→  'then',
 33→  'else',
 34→  'dependentRequired',
 35→  'dependentSchemas',
 36→  'prefixItems',
 37→  'unevaluatedProperties',
 38→  'unevaluatedItems',
 39→  'contentMediaType',
 40→  'contentEncoding',
 41→]);
 42→
 43→/**
 44→ * Sanitize a JSON Schema so it conforms to what Claude's API accepts
 45→ * (JSON Schema draft 2020-12 subset). Strips unsupported keywords,
 46→ * fixes array-style `type`, removes old `$schema` declarations, and
 47→ * wraps top-level composition keywords in an object wrapper.
 48→ */
 49→export function sanitizeInputSchema(
 50→  schema: Record<string, unknown> | null | undefined
 51→): Record<string, unknown> {
 52→  const fallback = { type: 'object' as const, properties: {} };
 53→  if (!schema || typeof schema !== 'object') return fallback;
 54→
 55→  try {
 56→    const cleaned = sanitizeSchemaNode(structuredClone(schema), true);
 57→    // Ensure root is always type: object
 58→    if (!cleaned.type) cleaned.type = 'object';
 59→    return cleaned;
 60→  } catch {
 61→    // If sanitization itself fails, return safe fallback
 62→    return fallback;
 63→  }
 64→}
 65→
 66→function isSchemaObject(value: unknown): value is Record<string, unknown> {
 67→  return typeof value === 'object' && value !== null && !Array.isArray(value);
 68→}
 69→
 70→/** Recursively sanitize a child schema node */
 71→function sanitizeChild(value: unknown): unknown {
 72→  return isSchemaObject(value) ? sanitizeSchemaNode(value, false) : value;
 73→}
 74→
 75→/** Sanitize all values in an object-of-schemas (e.g. properties, $defs) */
 76→function sanitizeObjectMap(map: Record<string, unknown>): void {
 77→  for (const [key, value] of Object.entries(map)) {
 78→    if (isSchemaObject(value)) {
 79→      map[key] = sanitizeSchemaNode(value, false);
 80→    }
 81→  }
 82→}
 83→
 84→/** Strip unsupported keywords and fix value-level issues */
 85→function stripUnsupportedKeywords(node: Record<string, unknown>): void {
 86→  delete node.$schema;
 87→  for (const key of UNSUPPORTED_KEYWORDS) {
 88→    delete node[key];
 89→  }
 90→  // minItems: only 0 and 1 are supported
 91→  if (typeof node.minItems === 'number' && node.minItems > 1) {
 92→    delete node.minItems;
 93→  }
 94→}
 95→
 96→/** Normalize and validate the `type` field */
 97→function normalizeType(node: Record<string, unknown>): void {
 98→  if (Array.isArray(node.type)) {
 99→    // Array-style type like ["string", "null"] → anyOf
100→    const types = (node.type as string[]).filter((t) => VALID_TYPES.has(t));
101→    if (types.length === 1) {
102→      node.type = types[0];
103→    } else if (types.length > 1) {
104→      delete node.type;
105→      node.anyOf = types.map((t) => ({ type: t }));
106→    } else {
107→      delete node.type;
108→    }
109→  } else if (typeof node.type === 'string' && !VALID_TYPES.has(node.type)) {
110→    // Invalid type like "string[]" or "'markdown' | 'mdx'" — remove it
111→    delete node.type;
112→  }
113→}
114→
115→/** Fix conflicting type + oneOf/anyOf (e.g. type:"object" with oneOf:[{type:"string"}, ...]) */
116→function fixConflictingComposition(node: Record<string, unknown>): void {
117→  if (typeof node.type !== 'string') return;
118→  for (const keyword of ['oneOf', 'anyOf'] as const) {
119→    if (!Array.isArray(node[keyword])) continue;
120→    const variants = node[keyword] as Record<string, unknown>[];
121→    const hasConflict = variants.some(
122→      (v) => isSchemaObject(v) && typeof v.type === 'string' && v.type !== node.type
123→    );
124→    if (hasConflict) {
125→      // The composition keyword is more specific — drop the conflicting wrapper type
126→      delete node.type;
127→      // Also clean up empty properties/additionalProperties left from the wrapper
128→      if (
129→        isSchemaObject(node.properties) &&
130→        Object.keys(node.properties as Record<string, unknown>).length === 0
131→      ) {
132→        delete node.properties;
133→      }
134→      delete node.additionalProperties;
135→      break;
136→    }
137→  }
138→}
139→
140→/** Remove external $ref URIs (keep internal refs like "#/$defs/Foo") */
141→function stripExternalRefs(node: Record<string, unknown>): void {
142→  if (typeof node.$ref === 'string' && /^https?:\/\//.test(node.$ref)) {
143→    delete node.$ref;
144→    if (!node.type) node.type = 'object';
145→  }
146→}
147→
148→/** Recurse into all nested schema locations */
149→function sanitizeNestedSchemas(node: Record<string, unknown>): void {
150→  if (isSchemaObject(node.properties))
151→    sanitizeObjectMap(node.properties as Record<string, unknown>);
152→  if (isSchemaObject(node.items))
153→    node.items = sanitizeSchemaNode(node.items as Record<string, unknown>, false);
154→  if (isSchemaObject(node.additionalProperties)) {
155→    node.additionalProperties = sanitizeSchemaNode(
156→      node.additionalProperties as Record<string, unknown>,
157→      false
158→    );
159→  }
160→  for (const keyword of ['anyOf', 'oneOf', 'allOf'] as const) {
161→    if (Array.isArray(node[keyword])) {
162→      node[keyword] = (node[keyword] as unknown[]).map(sanitizeChild);
163→    }
164→  }
165→  for (const defsKey of ['$defs', 'definitions'] as const) {
166→    if (isSchemaObject(node[defsKey])) sanitizeObjectMap(node[defsKey] as Record<string, unknown>);
167→  }
168→}
169→
170→function sanitizeSchemaNode(
171→  node: Record<string, unknown>,
172→  isRoot: boolean
173→): Record<string, unknown> {
174→  stripUnsupportedKeywords(node);
175→  normalizeType(node);
176→  fixConflictingComposition(node);
177→
178→  // Claude rejects top-level oneOf/allOf/anyOf
179→  if (isRoot && !node.type && (node.oneOf || node.allOf || node.anyOf)) {
180→    return { type: 'object', properties: {} };
181→  }
182→
183→  stripExternalRefs(node);
184→  sanitizeNestedSchemas(node);
185→  return node;
186→}
