188→/**
189→ * Bridge tool definition from the BridgeConnection.tools JSON
190→ */
191→export interface BridgeTool {
192→  serverId: string;
193→  serverName: string;
194→  name: string;
195→  description?: string;
196→  inputSchema?: Record<string, unknown>;
197→}
198→
199→/**
200→ * Sanitize package name and tool name into a valid MCP tool name.
201→ * MCP tool names must match ^[a-zA-Z0-9_-]+ and be at most 64 characters.
202→ *
203→ * Example: @tpmjs/hello + helloWorldTool → tpmjs-hello--helloWorldTool
204→ * Example: @tpmjs/tools-sprites-foo + spritesBarTool → sprites-foo--spritesBar
205→ */
206→export function sanitizeMcpName(packageName: string, toolName: string): string {
207→  // Remove @ and convert / to -
208→  let sanitizedPkg = packageName.replace(/^@/, '').replace(/\//g, '-');
209→
210→  // Remove common prefixes to shorten
211→  sanitizedPkg = sanitizedPkg.replace(/^tpmjs-tools-/, '');
212→  sanitizedPkg = sanitizedPkg.replace(/^tpmjs-/, '');
213→
214→  // Remove 'Tool' suffix from tool name
215→  const sanitizedTool = toolName.replace(/Tool$/, '');
216→
217→  const fullName = `${sanitizedPkg}--${sanitizedTool}`;
218→
219→  // Ensure we stay under 64 character limit
220→  if (fullName.length <= 64) {
221→    return fullName;
222→  }
223→
224→  // If still too long, truncate package name to fit
225→  const maxPkgLen = 64 - sanitizedTool.length - 2; // 2 for '--'
226→  if (maxPkgLen > 10) {
227→    return `${sanitizedPkg.slice(0, maxPkgLen)}--${sanitizedTool}`;
228→  }
229→
230→  // Last resort: truncate both
231→  return fullName.slice(0, 64);
232→}
233→
234→/**
235→ * Create MCP name for a bridge tool
236→ * Example: chrome-devtools + screenshot → bridge--chrome-devtools--screenshot
237→ */
238→export function sanitizeBridgeToolName(serverId: string, toolName: string): string {
239→  // Sanitize serverId and toolName to only allow valid MCP characters
240→  const sanitizedServer = serverId.replace(/[^a-zA-Z0-9_-]/g, '-');
241→  const sanitizedTool = toolName.replace(/[^a-zA-Z0-9_-]/g, '-');
242→  return `bridge--${sanitizedServer}--${sanitizedTool}`;
243→}
244→
245→/**
246→ * Convert a TPMJS Tool to an MCP tool definition.
247→ * Sanitizes inputSchema to ensure it conforms to Claude's JSON Schema subset.
248→ */
249→export function convertToMcpTool(tool: Tool & { package: Package }): McpToolDefinition {
250→  return {
251→    name: sanitizeMcpName(tool.package.npmPackageName, tool.name),
252→    description: tool.description,
253→    inputSchema: sanitizeInputSchema(tool.inputSchema as Record<string, unknown>),
254→  };
255→}
256→
257→/**
258→ * Parsed tool name result - either a registry tool or a bridge tool
259→ */
260→export type ParsedToolName =
261→  | {
262→      type: 'registry';
263→      packageName: string;
264→      literalPackageName: string;
265→      toolName: string;
266→      possiblePackages: string[];
267→      possibleToolNames: string[];
268→    }
269→  | { type: 'bridge'; serverId: string; toolName: string };
270→
271→/**
272→ * Parse an MCP tool name back into its components.
273→ * Handles both registry tools and bridge tools.
274→ *
275→ * Registry: tpmjs-hello--helloWorldTool → { type: 'registry', packageName: "@tpmjs/hello", toolName: "helloWorldTool" }
276→ * Shortened: sprites-get--spritesGet → tries @tpmjs/tools-sprites-get, @tpmjs/sprites-get, sprites-get
277→ * Bridge: bridge--chrome-devtools--screenshot → { type: 'bridge', serverId: "chrome-devtools", toolName: "screenshot" }
278→ */
279→export function parseToolName(mcpName: string): ParsedToolName | null {
280→  // Check if it's a bridge tool
281→  const bridgeMatch = mcpName.match(/^bridge--([^-]+(?:-[^-]+)*)--(.+)$/);
282→  if (bridgeMatch?.[1] && bridgeMatch[2]) {
283→    return {
284→      type: 'bridge',
285→      serverId: bridgeMatch[1],
286→      toolName: bridgeMatch[2],
287→    };
288→  }
289→
290→  // Otherwise parse as registry tool
291→  const match = mcpName.match(/^(.+)--(.+)$/);
292→  if (!match || !match[1] || !match[2]) return null;
293→
294→  const pkg = match[1];
295→  const toolName = match[2];
296→
297→  // Add back 'Tool' suffix if it was removed (try both with and without)
298→  // The handler will try to find the tool with both variants
299→  const toolNameWithSuffix = toolName.endsWith('Tool') ? toolName : `${toolName}Tool`;
300→
301→  // Generate possible package names to try:
302→  // 1. @tpmjs/tools-{pkg} (shortened tpmjs-tools- prefix)
303→  // 2. @tpmjs/{pkg} (shortened tpmjs- prefix)
304→  // 3. All @{scope}/{name} splits (try every dash as the scope/name boundary)
305→  //    e.g. "perplexity-ai-ai-sdk" → @perplexity/ai-ai-sdk, @perplexity-ai/ai-sdk, @perplexity-ai-ai/sdk
306→  // 4. {pkg} as literal (non-scoped packages)
307→  const possiblePackages = [`@tpmjs/tools-${pkg}`, `@tpmjs/${pkg}`];
308→
309→  // Try every dash position as the scope/name boundary for scoped packages
310→  const dashPositions = [...pkg.matchAll(/-/g)].map((m) => m.index);
311→  for (const pos of dashPositions) {
312→    possiblePackages.push(`@${pkg.slice(0, pos)}/${pkg.slice(pos + 1)}`);
313→  }
314→
315→  possiblePackages.push(pkg);
316→
317→  // Return the first scoped interpretation as primary, with literal as fallback
318→  return {
319→    type: 'registry',
320→    packageName: possiblePackages[0]!, // @tpmjs/tools-{pkg}
321→    literalPackageName: pkg,
322→    toolName: toolNameWithSuffix,
323→    // Additional candidates for the handler to try
324→    possiblePackages,
325→    possibleToolNames: [toolNameWithSuffix, toolName],
326→  } as ParsedToolName;
327→}
328→
329→/**
330→ * Convert a bridge tool definition to an MCP tool definition.
331→ * Sanitizes inputSchema to ensure it conforms to Claude's JSON Schema subset.
332→ */
333→export function convertBridgeToolToMcp(
334→  tool: BridgeTool,
335→  displayName?: string | null
336→): McpToolDefinition {
337→  return {
338→    name: sanitizeBridgeToolName(tool.serverId, tool.name),
339→    description: displayName
340→      ? `[${tool.serverName}] ${displayName}`
341→      : tool.description || `${tool.name} from ${tool.serverName}`,
342→    inputSchema: sanitizeInputSchema(tool.inputSchema),
343→  };
344→}
