412→        return {
413→          jsonrpc: '2.0',
414→          id: requestId,
415→          result: {
416→            content: [
417→              {
418→                type: 'text',
419→                text: 'Error: Bridge connection appears stale. Please check if the bridge CLI is running.',
420→              },
421→            ],
422→            isError: true,
423→          },
424→        };
425→      }
426→    }
