 1→import { createCipheriv, createDecipheriv, createHash, randomBytes } from 'node:crypto';
 2→
 3→const ALGORITHM = 'aes-256-gcm';
 4→
 5→function getEncryptionKey(): Buffer {
 6→  const secret = process.env.API_KEY_ENCRYPTION_SECRET;
 7→  if (!secret) {
 8→    throw new Error('API_KEY_ENCRYPTION_SECRET environment variable is not set');
 9→  }
10→  return createHash('sha256').update(secret).digest();
11→}
12→
13→/**
14→ * Encrypts an API key using AES-256-GCM
15→ */
16→export function encryptApiKey(apiKey: string): { encrypted: string; iv: string } {
17→  const key = getEncryptionKey();
18→  const iv = randomBytes(16);
19→  const cipher = createCipheriv(ALGORITHM, key, iv);
20→
21→  let encrypted = cipher.update(apiKey, 'utf8', 'hex');
22→  encrypted += cipher.final('hex');
23→
24→  // Append the auth tag to the encrypted data
25→  const authTag = cipher.getAuthTag().toString('hex');
26→  encrypted += authTag;
27→
28→  return {
29→    encrypted,
30→    iv: iv.toString('hex'),
31→  };
32→}
33→
34→/**
35→ * Decrypts an API key using AES-256-GCM
36→ */
37→export function decryptApiKey(encrypted: string, iv: string): string {
38→  try {
39→    const key = getEncryptionKey();
40→
41→    // Extract the auth tag (last 32 hex chars = 16 bytes)
42→    const authTag = Buffer.from(encrypted.slice(-32), 'hex');
43→    const encryptedData = encrypted.slice(0, -32);
44→
45→    const decipher = createDecipheriv(ALGORITHM, key, Buffer.from(iv, 'hex'));
46→    decipher.setAuthTag(authTag);
47→
48→    let decrypted = decipher.update(encryptedData, 'hex', 'utf8');
49→    decrypted += decipher.final('utf8');
50→
51→    return decrypted;
52→  } catch (error) {
53→    // Provide a more helpful error message
54→    const message = error instanceof Error ? error.message : 'Unknown error';
55→    if (message.includes('Unsupported state') || message.includes('unable to authenticate')) {
56→      throw new Error(
57→        'API key decryption failed. The encryption secret may have changed. ' +
58→          'Please re-save your API key in Settings > API Keys.'
59→      );
60→    }
61→    throw error;
62→  }
63→}
64→
65→/**
66→ * Creates a masked version of an API key for display (e.g., "sk-...XXXX")
67→ */
68→export function maskApiKey(apiKey: string): string {
69→  if (apiKey.length <= 8) return '****';
70→
71→  const prefix = apiKey.slice(0, 4);
72→  const suffix = apiKey.slice(-4);
73→  return `${prefix}...${suffix}`;
74→}
75→
76→/**
77→ * Gets the last 4 characters of an API key for identification
78→ */
79→export function getKeyHint(apiKey: string): string {
80→  if (apiKey.length < 4) return apiKey;
81→  return apiKey.slice(-4);
82→}
