 53→/**
 54→ * Handle MCP tools/list request
 55→ */
 56→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: MCP tools list handler with schema transformation
 57→export async function handleToolsList(
 58→  collectionId: string,
 59→  requestId: JsonRpcId
 60→): Promise<JsonRpcResponse> {
 61→  try {
 62→    const collection = await withTimeout(
 63→      prisma.collection.findUnique({
 64→        where: { id: collectionId },
 65→        include: {
 66→          tools: {
 67→            include: { tool: { include: { package: true } } },
 68→            orderBy: { position: 'asc' },
 69→          },
 70→          bridgeTools: true,
 71→          user: {
 72→            include: {
 73→              bridgeConnection: true,
 74→            },
 75→          },
 76→        },
 77→      }),
 78→      DB_TIMEOUT_MS,
 79→      'Database query timed out'
 80→    );
 81→
 82→    // Convert registry tools to MCP format
 83→    const registryTools = collection?.tools.map((ct) => convertToMcpTool(ct.tool)) ?? [];
 84→
 85→    // Convert bridge tools to MCP format
 86→    const bridgeTools: ReturnType<typeof convertBridgeToolToMcp>[] = [];
 87→
 88→    if (collection?.bridgeTools.length && collection.user.bridgeConnection) {
 89→      const bridgeConnection = collection.user.bridgeConnection;
 90→      const availableBridgeTools = (bridgeConnection.tools as unknown as BridgeTool[]) || [];
 91→
 92→      // Only include bridge tools if bridge is connected
 93→      if (bridgeConnection.status === 'connected') {
 94→        for (const collectionBridgeTool of collection.bridgeTools) {
 95→          // Find the tool definition from the bridge connection
 96→          const bridgeTool = availableBridgeTools.find(
 97→            (bt) =>
 98→              bt.serverId === collectionBridgeTool.serverId &&
 99→              bt.name === collectionBridgeTool.toolName
100→          );
101→
102→          if (bridgeTool) {
103→            bridgeTools.push(convertBridgeToolToMcp(bridgeTool, collectionBridgeTool.displayName));
104→          }
105→        }
106→      }
107→    }
108→
109→    return {
110→      jsonrpc: '2.0',
111→      id: requestId,
112→      result: { tools: [...registryTools, ...bridgeTools] },
113→    };
114→  } catch (error) {
115→    console.error('[MCP tools/list] Error:', error);
116→    return {
117→      jsonrpc: '2.0',
118→      id: requestId,
119→      error: { code: -32603, message: error instanceof Error ? error.message : 'Internal error' },
120→    };
121→  }
122→}
