124→interface ToolsCallParams {
125→  name: string;
126→  arguments?: Record<string, unknown>;
127→  env?: Record<string, string>; // Caller-provided env vars for non-owners
128→}
129→
130→export interface TrackingContext {
131→  userId?: string;
132→  apiKeyId?: string;
133→  collectionId?: string;
134→  source: TrackExecutionParams['source'];
135→}
