137→/**
138→ * Handle MCP tools/call request
139→ * @param callerEnvVars - Optional env vars from caller (non-owner accessing public collection)
140→ *                        When provided, these are used INSTEAD of collection's stored env vars
141→ * @param trackingCtx - Optional tracking context for execution event tracking
142→ * @param headerEnvVars - Optional env vars extracted from request headers (e.g. tpmjs-api-key → TPMJS_API_KEY)
143→ */
144→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: MCP tool execution with env resolution, tracking, and error handling
145→export async function handleToolsCall(
146→  collectionId: string,
147→  params: ToolsCallParams,
148→  requestId: JsonRpcId,
149→  callerEnvVars?: Record<string, string>,
150→  trackingCtx?: TrackingContext,
151→  headerEnvVars?: Record<string, string>
152→): Promise<JsonRpcResponse> {
153→  try {
154→    const parsed = parseToolName(params.name);
155→    if (!parsed) {
156→      return {
157→        jsonrpc: '2.0',
158→        id: requestId,
159→        error: { code: -32602, message: `Invalid tool name: ${params.name}` },
160→      };
161→    }
162→
163→    // Handle bridge tool calls
164→    if (parsed.type === 'bridge') {
165→      return handleBridgeToolCall(
166→        collectionId,
167→        parsed.serverId,
168→        parsed.toolName,
169→        params.arguments ?? {},
170→        requestId
171→      );
172→    }
173→
174→    // Handle registry tool calls
175→    // Verify tool exists in collection and get executor config
176→    const collection = await withTimeout(
177→      prisma.collection.findUnique({
178→        where: { id: collectionId },
179→        select: {
180→          executorType: true,
181→          executorConfig: true,
182→          envVars: true,
183→          tools: {
184→            include: { tool: { include: { package: true } } },
185→          },
186→        },
187→      }),
188→      DB_TIMEOUT_MS,
189→      'Database query timed out'
190→    );
191→
192→    // Try all possible package name and tool name combinations
193→    // This handles both old format (full package name) and new shortened format
194→    type CollectionTool = NonNullable<typeof collection>['tools'][number];
195→    let collectionTool: CollectionTool | undefined;
196→
197→    for (const pkgName of parsed.possiblePackages) {
198→      for (const toolName of parsed.possibleToolNames) {
199→        collectionTool = collection?.tools.find(
200→          (ct) => ct.tool.package.npmPackageName === pkgName && ct.tool.name === toolName
201→        );
202→        if (collectionTool) break;
203→      }
204→      if (collectionTool) break;
205→    }
206→
207→    if (!collectionTool) {
208→      return {
209→        jsonrpc: '2.0',
210→        id: requestId,
211→        error: { code: -32602, message: `Tool not found in collection: ${params.name}` },
212→      };
213→    }
214→
215→    // Get the actual package name and version that matched
216→    const actualPackageName = collectionTool.tool.package.npmPackageName;
217→    const actualVersion = collectionTool.tool.package.npmVersion;
218→
219→    // When caller provides env vars (non-owner), validate required env vars
220→    if (callerEnvVars !== undefined) {
221→      const packageEnv = collectionTool.tool.package.env as TpmjsEnv[] | null;
222→      if (packageEnv && Array.isArray(packageEnv)) {
223→        const missingVars = packageEnv.filter(
224→          (env) => env.required !== false && !env.default && !callerEnvVars[env.name]
225→        );
226→
227→        if (missingVars.length > 0) {
228→          return {
229→            jsonrpc: '2.0',
230→            id: requestId,
231→            error: {
232→              code: -32602,
233→              message: 'Missing required environment variables',
234→              data: {
235→                missingVars: missingVars.map((e) => ({
236→                  name: e.name,
237→                  description: e.description,
238→                })),
239→              },
240→            },
241→          };
242→        }
243→      }
244→    }
245→
246→    // Resolve executor configuration (collection config only for MCP - no agent context)
247→    const executorConfig = parseExecutorConfig(
248→      collection?.executorType,
249→      collection?.executorConfig
250→    );
251→
252→    // Execute via resolved executor
253→    // Use caller-provided env vars if given (non-owner), otherwise use collection's stored env vars
254→    // Merge in any env vars extracted from request headers (e.g. tpmjs-api-key → TPMJS_API_KEY)
255→    const effectiveEnvVars = {
256→      ...(callerEnvVars ?? (collection?.envVars as Record<string, string>) ?? {}),
257→      ...headerEnvVars,
258→    };
259→    // Pass explicit version to avoid Deno HTTP import cache issues with @latest
260→    // Use actual tool name from DB, not parsed name (which may have wrong suffix)
261→    const execStart = Date.now();
262→    const result = await executeWithExecutor(executorConfig, {
263→      packageName: actualPackageName,
264→      name: collectionTool.tool.name,
265→      version: actualVersion,
266→      params: params.arguments ?? {},
267→      env: Object.keys(effectiveEnvVars).length > 0 ? effectiveEnvVars : undefined,
268→    });
269→    const execDurationMs = Date.now() - execStart;
270→
271→    // Track execution event (fire-and-forget)
272→    if (trackingCtx) {
273→      trackExecution({
274→        eventType: 'tool_call',
275→        source: trackingCtx.source,
276→        userId: trackingCtx.userId,
277→        apiKeyId: trackingCtx.apiKeyId,
278→        toolId: collectionTool.tool.id,
279→        collectionId: trackingCtx.collectionId ?? collectionId,
280→        toolName: collectionTool.tool.name,
281→        packageName: actualPackageName,
282→        status: result.success ? 'success' : 'error',
283→        durationMs: execDurationMs,
284→        errorMessage: result.success ? undefined : String(result.error),
285→      });
286→
287→      // Log user-facing activity (fire-and-forget)
288→      if (trackingCtx.userId) {
289→        logActivity({
290→          userId: trackingCtx.userId,
291→          type: 'TOOL_EXECUTED',
292→          targetName: collectionTool.tool.name,
293→          targetType: 'tool',
294→          toolId: collectionTool.tool.id,
295→          collectionId: trackingCtx.collectionId ?? collectionId,
296→          metadata: {
297→            source: trackingCtx.source,
298→            status: result.success ? 'success' : 'error',
299→            packageName: actualPackageName,
300→          },
301→        });
302→      }
303→    }
304→
305→    if (!result.success) {
306→      return {
307→        jsonrpc: '2.0',
308→        id: requestId,
309→        result: {
310→          content: [{ type: 'text', text: `Error: ${result.error}` }],
311→          isError: true,
312→        },
313→      };
314→    }
315→
316→    return {
317→      jsonrpc: '2.0',
318→      id: requestId,
319→      result: {
320→        content: [
321→          {
322→            type: 'text',
323→            text:
324→              typeof result.output === 'string'
325→                ? result.output
326→                : JSON.stringify(result.output, null, 2),
327→          },
328→        ],
329→      },
330→    };
331→  } catch (error) {
332→    console.error('[MCP tools/call] Error:', error);
333→    return {
334→      jsonrpc: '2.0',
335→      id: requestId,
336→      error: { code: -32603, message: error instanceof Error ? error.message : 'Internal error' },
337→    };
338→  }
339→}
