341→/**
342→ * Handle a bridge tool call by routing it through the user's bridge connection
343→ */
344→async function handleBridgeToolCall(
345→  collectionId: string,
346→  serverId: string,
347→  toolName: string,
348→  args: Record<string, unknown>,
349→  requestId: JsonRpcId
350→): Promise<JsonRpcResponse> {
351→  try {
352→    // Get the collection's owner and their bridge connection
353→    const collection = await withTimeout(
354→      prisma.collection.findUnique({
355→        where: { id: collectionId },
356→        include: {
357→          bridgeTools: {
358→            where: { serverId, toolName },
359→          },
360→          user: {
361→            include: { bridgeConnection: true },
362→          },
363→        },
364→      }),
365→      DB_TIMEOUT_MS,
366→      'Database query timed out'
367→    );
368→
369→    if (!collection) {
370→      return {
371→        jsonrpc: '2.0',
372→        id: requestId,
373→        error: { code: -32602, message: 'Collection not found' },
374→      };
375→    }
376→
377→    // Verify the bridge tool exists in the collection
378→    const bridgeTool = collection.bridgeTools[0];
379→    if (!bridgeTool) {
380→      return {
381→        jsonrpc: '2.0',
382→        id: requestId,
383→        error: {
384→          code: -32602,
385→          message: `Bridge tool not found in collection: ${serverId}/${toolName}`,
386→        },
387→      };
388→    }
389→
390→    // Verify the user has an active bridge connection
391→    const bridgeConnection = collection.user.bridgeConnection;
392→    if (!bridgeConnection || bridgeConnection.status !== 'connected') {
393→      return {
394→        jsonrpc: '2.0',
395→        id: requestId,
396→        result: {
397→          content: [
398→            {
399→              type: 'text',
400→              text: 'Error: Bridge is not connected. Start the bridge CLI to use bridge tools.',
401→            },
402→          ],
403→          isError: true,
404→        },
405→      };
406→    }
407→
408→    // Check if the bridge is stale (not seen in 2 minutes)
409→    if (bridgeConnection.lastSeen) {
410→      const staleThreshold = 2 * 60 * 1000; // 2 minutes
411→      if (Date.now() - bridgeConnection.lastSeen.getTime() > staleThreshold) {
412→        return {
413→          jsonrpc: '2.0',
414→          id: requestId,
415→          result: {
416→            content: [
417→              {
418→                type: 'text',
419→                text: 'Error: Bridge connection appears stale. Please check if the bridge CLI is running.',
420→              },
421→            ],
422→            isError: true,
423→          },
424→        };
425→      }
426→    }
427→
428→    // Generate a unique call ID
429→    const callId = `${Date.now()}-${Math.random().toString(36).slice(2, 11)}`;
430→
431→    // Queue the tool call for the bridge to pick up
432→    queueBridgeToolCall(collection.user.id, callId, serverId, toolName, args);
433→
434→    // Wait for the result (with 5 minute timeout)
435→    const result = await waitForBridgeResult(callId, 300000);
436→
437→    if (result.error) {
438→      return {
439→        jsonrpc: '2.0',
440→        id: requestId,
441→        result: {
442→          content: [{ type: 'text', text: `Error: ${result.error.message}` }],
443→          isError: true,
444→        },
445→      };
446→    }
447→
448→    // Format the result
449→    const content = result.result as { content?: unknown[]; isError?: boolean } | undefined;
450→    if (content?.content) {
451→      return {
452→        jsonrpc: '2.0',
453→        id: requestId,
454→        result: {
455→          content: content.content,
456→          isError: content.isError,
457→        },
458→      };
459→    }
460→
461→    return {
462→      jsonrpc: '2.0',
463→      id: requestId,
464→      result: {
465→        content: [
466→          {
467→            type: 'text',
468→            text:
469→              typeof result.result === 'string'
470→                ? result.result
471→                : JSON.stringify(result.result, null, 2),
