245→/**
246→ * Convert a TPMJS Tool to an MCP tool definition.
247→ * Sanitizes inputSchema to ensure it conforms to Claude's JSON Schema subset.
248→ */
249→export function convertToMcpTool(tool: Tool & { package: Package }): McpToolDefinition {
250→  return {
251→    name: sanitizeMcpName(tool.package.npmPackageName, tool.name),
252→    description: tool.description,
253→    inputSchema: sanitizeInputSchema(tool.inputSchema as Record<string, unknown>),
254→  };
