 7→/**
 8→ * POST /api/tools/validate
 9→ * Validate a tpmjs field and determine its tier
10→ *
11→ * Body: JSON object representing the tpmjs field
12→ *
13→ * Returns:
14→ * - valid: boolean indicating if the field is valid
15→ * - tier: 'minimal' | 'rich' | null
16→ * - data: validated data if valid
17→ * - errors: validation errors if invalid
18→ */
19→export async function POST(request: NextRequest) {
20→  // Check rate limit
21→  const rateLimitResponse = checkRateLimit(request);
22→  if (rateLimitResponse) {
23→    return rateLimitResponse;
24→  }
25→
26→  try {
27→    const body = await request.json();
28→
29→    // Validate the tpmjs field
30→    const result = validateTpmjsField(body);
31→
32→    // Format errors for better readability
33→    if (!result.valid && result.errors) {
34→      return NextResponse.json(
35→        {
36→          success: false,
37→          valid: false,
38→          tier: null,
39→          errors: result.errors.issues.map((issue) => ({
40→            path: issue.path.join('.'),
41→            message: issue.message,
42→            code: issue.code,
43→          })),
44→        },
45→        { status: 400 }
46→      );
47→    }
48→
49→    return NextResponse.json({
50→      success: true,
51→      valid: result.valid,
52→      tier: result.tier,
53→      data: result.data,
54→    });
55→  } catch (error) {
56→    console.error('Error validating tpmjs field:', error);
57→
58→    // Handle JSON parsing errors
59→    if (error instanceof SyntaxError) {
60→      return NextResponse.json(
61→        {
62→          success: false,
63→          error: 'Invalid JSON',
64→          message: 'The request body must be valid JSON',
65→        },
66→        { status: 400 }
67→      );
68→    }
69→
70→    return NextResponse.json(
71→      {
72→        success: false,
73→        error: 'Validation failed',
74→        message: error instanceof Error ? error.message : 'Unknown error',
75→      },
76→      { status: 500 }
77→    );
78→  }
79→}
