 97→
 98→export default function CollectionDetailPage(): React.ReactElement {
 99→  const params = useParams();
100→  const router = useRouter();
101→  const searchParams = useSearchParams();
102→  const collectionId = params.id as string;
103→
104→  // Get initial tab from URL or default to 'tools'
105→  const tabFromUrl = searchParams.get('tab') as TabId | null;
106→  const initialTab = tabFromUrl && VALID_TABS.includes(tabFromUrl) ? tabFromUrl : 'tools';
107→
108→  const [collection, setCollection] = useState<Collection | null>(null);
109→  const [isLoading, setIsLoading] = useState(true);
110→  const [error, setError] = useState<string | null>(null);
111→  const [activeTab, setActiveTab] = useState<TabId>(initialTab);
112→  const [isUpdating, setIsUpdating] = useState(false);
113→  const [removingToolId, setRemovingToolId] = useState<string | null>(null);
114→  const [isDeleting, setIsDeleting] = useState(false);
115→  const [executorConfig, setExecutorConfig] = useState<ExecutorConfig | null>(null);
116→  const [envVars, setEnvVars] = useState<Record<string, string> | null>(null);
117→  const [showClaudeConfig, setShowClaudeConfig] = useState(false);
118→
119→  // Update URL when tab changes
