121→    const newTab = tabId as TabId;
122→    setActiveTab(newTab);
123→    const newParams = new URLSearchParams(searchParams.toString());
124→    if (newTab === 'tools') {
125→      newParams.delete('tab');
126→    } else {
127→      newParams.set('tab', newTab);
128→    }
129→    const queryString = newParams.toString();
130→    router.replace(
131→      `/dashboard/collections/${collectionId}${queryString ? `?${queryString}` : ''}`,
132→      {
133→        scroll: false,
134→      }
135→    );
136→  };
137→
138→  const fetchCollection = useCallback(async () => {
139→    try {
140→      const response = await fetch(`/api/collections/${collectionId}`);
141→      const data = await response.json();
142→
143→      if (data.success) {
144→        setCollection(data.data);
145→        if (data.data.executorType === 'custom_url' && data.data.executorConfig) {
146→          setExecutorConfig({
147→            type: 'custom_url',
148→            url: data.data.executorConfig.url,
149→            apiKey: data.data.executorConfig.apiKey,
150→          });
151→        } else {
152→          setExecutorConfig(data.data.executorType ? { type: 'default' } : null);
153→        }
154→        if (data.data.envVars && typeof data.data.envVars === 'object') {
155→          setEnvVars(data.data.envVars as Record<string, string>);
156→        } else {
157→          setEnvVars(null);
158→        }
159→      } else {
160→        if (data.error?.code === 'UNAUTHORIZED') {
161→          router.push('/sign-in');
162→          return;
163→        }
164→        if (data.error?.code === 'NOT_FOUND') {
165→          router.push('/dashboard/collections');
166→          return;
167→        }
168→        setError(data.error?.message || 'Failed to fetch collection');
169→      }
170→    } catch (err) {
171→      console.error('Failed to fetch collection:', err);
172→      setError('Failed to fetch collection');
173→    } finally {
174→      setIsLoading(false);
175→    }
176→  }, [collectionId, router]);
177→
178→  useEffect(() => {
179→    fetchCollection();
180→  }, [fetchCollection]);
181→
182→  const handleUpdate = async (data: { name: string; description?: string; isPublic: boolean }) => {
183→    if (!collection) return;
184→    setIsUpdating(true);
185→
186→    const updatePayload: Record<string, unknown> = { ...data };
187→    if (executorConfig) {
188→      updatePayload.executorType = executorConfig.type;
189→      if (executorConfig.type === 'custom_url') {
190→        updatePayload.executorConfig = {
