277→      toolId: tool.id,
278→      position: collection.tools.length,
279→      note: null,
280→      addedAt: new Date().toISOString(),
281→      tool: {
282→        id: tool.id,
283→        name: tool.name,
284→        description: tool.description,
285→        package: {
286→          id: '',
287→          npmPackageName: tool.package.npmPackageName,
288→          category: tool.package.category,
289→        },
290→      },
291→    };
292→
293→    setCollection((prev) =>
294→      prev
295→        ? {
296→            ...prev,
297→            toolCount: prev.toolCount + 1,
298→            tools: [...prev.tools, newTool],
299→          }
300→        : null
301→    );
302→  };
303→
304→  const handleRemoveTool = async (toolId: string) => {
305→    setRemovingToolId(toolId);
306→
307→    try {
308→      const response = await fetch(`/api/collections/${collectionId}/tools/${toolId}`, {
309→        method: 'DELETE',
310→      });
311→
312→      const result = await response.json();
313→
314→      if (result.success) {
315→        setCollection((prev) =>
316→          prev
317→            ? {
318→                ...prev,
319→                toolCount: prev.toolCount - 1,
320→                tools: prev.tools.filter((t) => t.toolId !== toolId),
321→              }
322→            : null
323→        );
324→      } else {
325→        throw new Error(result.error?.message || 'Failed to remove tool');
326→      }
327→    } catch (err) {
328→      console.error('Failed to remove tool:', err);
329→      alert('Failed to remove tool');
330→    } finally {
331→      setRemovingToolId(null);
332→    }
333→  };
334→
335→  if (isLoading) {
336→    return (
337→      <DashboardLayout title="Loading..." showBackButton backUrl="/dashboard/collections">
338→        <div className="animate-pulse">
339→          <div className="h-8 bg-surface-secondary rounded w-48 mb-4" />
340→          <div className="h-4 bg-surface-secondary rounded w-96 mb-8" />
341→          <div className="h-12 bg-surface-secondary rounded mb-6" />
342→          <div className="space-y-3">
343→            {[1, 2, 3].map((i) => (
344→              <div key={i} className="h-24 bg-surface-secondary rounded" />
345→            ))}
346→          </div>
347→        </div>
348→      </DashboardLayout>
349→    );
350→  }
351→
352→  if (error || !collection) {
353→    return (
354→      <DashboardLayout title="Error" showBackButton backUrl="/dashboard/collections">
355→        <div className="text-center py-16">
356→          <Icon icon="alertCircle" size="lg" className="mx-auto text-error mb-4" />
357→          <h2 className="text-lg font-medium text-foreground mb-2">Error</h2>
358→          <p className="text-foreground-secondary mb-4">{error || 'Collection not found'}</p>
359→          <Link href="/dashboard/collections">
360→            <Button>Back to Collections</Button>
361→          </Link>
362→        </div>
363→      </DashboardLayout>
364→    );
365→  }
366→
367→  const existingToolIds = collection.tools.map((t) => t.toolId);
368→  const baseUrl = typeof window !== 'undefined' ? window.location.origin : 'https://tpmjs.com';
369→  const httpUrl = `${baseUrl}/api/mcp/${collection.user.username}/${collection.slug}/http`;
370→  const sseUrl = `${baseUrl}/api/mcp/${collection.user.username}/${collection.slug}/sse`;
371→
372→  // Claude Code CLI command (correct arg order: options before name and url)
373→  const claudeCodeCommand = `claude mcp add ${collection.slug} ${httpUrl} -t http -H "Authorization: Bearer YOUR_TPMJS_API_KEY"`;
374→
375→  // Claude Desktop native HTTP config
376→  const configSnippet = `{
377→  "mcpServers": {
378→    "${collection.slug}": {
379→      "type": "http",
380→      "url": "${httpUrl}",
381→      "headers": {
382→        "Authorization": "Bearer YOUR_TPMJS_API_KEY"
383→      }
384→    }
385→  }
386→}`;
387→
388→  const envVarsCount = envVars ? Object.keys(envVars).length : 0;
389→
390→  const tabs = [
391→    { id: 'tools' as const, label: 'Tools', count: collection.toolCount },
392→    { id: 'connect' as const, label: 'Connect' },
393→    {
394→      id: 'env-vars' as const,
395→      label: 'Env Vars',
396→      count: envVarsCount > 0 ? envVarsCount : undefined,
397→    },
398→    { id: 'settings' as const, label: 'Settings' },
399→  ];
400→
401→  return (
402→    <DashboardLayout
403→      title={collection.name}
404→      subtitle={collection.description || undefined}
405→      showBackButton
406→      backUrl="/dashboard/collections"
407→      actions={
408→        collection.isOwner && (
409→          <Button
410→            variant="ghost"
411→            size="sm"
412→            onClick={handleDelete}
413→            loading={isDeleting}
414→            disabled={isDeleting}
415→            className="text-error hover:text-error hover:bg-error/10"
416→          >
417→            <Icon icon="trash" size="sm" className="mr-1" />
418→            Delete
419→          </Button>
420→        )
421→      }
422→    >
423→      {/* Status badges */}
424→      <div className="flex items-center gap-2 mb-6">
425→        <Badge variant={collection.isPublic ? 'success' : 'secondary'}>
426→          {collection.isPublic ? 'Public' : 'Private'}
427→        </Badge>
428→        {executorConfig?.type === 'custom_url' && (
429→          <Badge variant="secondary">Custom Executor</Badge>
430→        )}
431→      </div>
432→
433→      {/* Tabs */}
434→      <Tabs tabs={tabs} activeTab={activeTab} onTabChange={handleTabChange} className="mb-6" />
435→
436→      {/* Tools Tab */}
437→      {activeTab === 'tools' && (
438→        <div>
439→          {/* Add Tools Search */}
440→          {collection.isOwner && (
441→            <div className="mb-6">
442→              <AddToolSearch
443→                collectionId={collection.id}
444→                existingToolIds={existingToolIds}
445→                onToolAdded={handleToolAdded}
446→              />
447→            </div>
448→          )}
449→
450→          {/* Tools Table */}
451→          <div className="bg-surface border border-border rounded-lg overflow-hidden">
452→            <Table>
453→              <TableHeader>
454→                <TableRow>
455→                  <TableHead className="w-[250px]">Tool</TableHead>
456→                  <TableHead>Description</TableHead>
457→                  <TableHead className="w-[120px]">Category</TableHead>
458→                  {collection.isOwner && (
459→                    <TableHead className="w-[80px] text-right">Actions</TableHead>
460→                  )}
461→                </TableRow>
462→              </TableHeader>
463→              <TableBody>
464→                {collection.tools.length === 0 ? (
465→                  <TableEmpty
466→                    colSpan={collection.isOwner ? 4 : 3}
467→                    icon={
468→                      <div className="w-16 h-16 rounded-full bg-primary/10 flex items-center justify-center">
469→                        <Icon icon="puzzle" size="lg" className="text-primary" />
470→                      </div>
471→                    }
472→                    title="No tools yet"
473→                    description="Search and add tools to this collection to get started."
474→                  />
475→                ) : (
476→                  collection.tools.map((ct) => (
477→                    <TableRow key={ct.id}>
478→                      <TableCell>
479→                        <Link
480→                          href={`/tool/${ct.tool.package.npmPackageName}/${ct.tool.name}`}
481→                          className="font-medium text-foreground hover:text-primary transition-colors"
482→                        >
483→                          {ct.tool.name}
484→                        </Link>
485→                        <div className="text-xs text-foreground-tertiary mt-0.5">
486→                          {ct.tool.package.npmPackageName}
487→                        </div>
488→                      </TableCell>
