506→                              disabled={removingToolId === ct.toolId}
507→                              className="text-error hover:text-error hover:bg-error/10"
508→                            >
509→                              <Icon icon="trash" size="xs" />
510→                            </Button>
511→                          </div>
512→                        </TableCell>
513→                      )}
514→                    </TableRow>
515→                  ))
516→                )}
517→              </TableBody>
518→            </Table>
519→          </div>
520→        </div>
521→      )}
522→
523→      {/* Connect Tab */}
524→      {activeTab === 'connect' && (
