533→                  <p className="text-sm text-foreground-secondary mt-1">
534→                    You need to set a username before you can share this collection as an MCP
535→                    server.
536→                  </p>
537→                  <Link href="/dashboard/settings/profile" className="inline-block mt-3">
538→                    <Button size="sm" variant="secondary">
539→                      <Icon icon="user" size="xs" className="mr-1" />
540→                      Set Username
541→                    </Button>
542→                  </Link>
543→                </div>
544→              </div>
545→            </div>
546→          )}
547→
548→          {/* Private collection notice */}
549→          {!collection.isPublic && (
550→            <div className="p-4 bg-primary/5 border border-primary/20 rounded-lg">
551→              <div className="flex items-start gap-3">
