605→
606→              <div className="mt-4">
607→                <button
608→                  type="button"
609→                  onClick={() => setShowClaudeConfig(!showClaudeConfig)}
610→                  className="flex items-center gap-2 text-sm text-primary hover:text-primary/80 transition-colors"
