613→                  <span>Show Claude Desktop config</span>
614→                </button>
615→
616→                {showClaudeConfig && (
617→                  <div className="mt-3 relative">
618→                    <pre className="p-4 bg-surface-secondary border border-border rounded-lg text-xs font-mono text-foreground-secondary overflow-x-auto">
619→                      {configSnippet}
