633→              <p className="mt-4 text-xs text-foreground-tertiary">
634→                Use these URLs with{' '}
635→                <Link href="/docs/tutorials/mcp" className="text-primary hover:underline">
636→                  Claude Desktop, Cursor, or any MCP client
637→                </Link>
638→                . Requires your{' '}
639→                <Link
640→                  href="/dashboard/settings/tpmjs-api-keys"
641→                  className="text-primary hover:underline"
642→                >
643→                  TPMJS API key
644→                </Link>{' '}
645→                for authentication.
646→              </p>
647→            </div>
648→          )}
649→        </div>
650→      )}
651→
652→      {/* Env Vars Tab */}
653→      {activeTab === 'env-vars' && collection.isOwner && (
654→        <div className="bg-surface border border-border rounded-lg p-6">
655→          <EnvVarsEditor
656→            value={envVars}
657→            onChange={async (newEnvVars) => {
658→              setEnvVars(newEnvVars);
659→              // Auto-save env vars with error handling
660→              try {
661→                const response = await fetch(`/api/collections/${collectionId}`, {
662→                  method: 'PATCH',
663→                  headers: { 'Content-Type': 'application/json' },
664→                  body: JSON.stringify({ envVars: newEnvVars }),
665→                });
666→                const result = await response.json();
667→                if (!result.success) {
668→                  console.error('Failed to save env vars:', result.error);
669→                  alert(`Failed to save environment variables: ${result.error || 'Unknown error'}`);
