682→
683→      {/* Env Vars Tab - Not Owner */}
684→      {activeTab === 'env-vars' && !collection.isOwner && (
685→        <div className="text-center py-16">
686→          <Icon icon="key" size="lg" className="mx-auto text-foreground-tertiary mb-4" />
687→          <h2 className="text-lg font-medium text-foreground mb-2">
688→            Environment Variables Unavailable
689→          </h2>
690→          <p className="text-foreground-secondary">
691→            You can only view environment variables for collections you own.
692→          </p>
693→        </div>
694→      )}
695→
696→      {/* Settings Tab */}
697→      {activeTab === 'settings' && collection.isOwner && (
698→        <div className="space-y-6">
699→          {/* Collection Info */}
700→          <div className="bg-surface border border-border rounded-lg p-6">
