724→                  if (newConfig.type === 'custom_url') {
725→                    updatePayload.executorConfig = {
726→                      url: newConfig.url,
727→                      apiKey: newConfig.apiKey,
728→                    };
729→                  } else {
730→                    updatePayload.executorConfig = null;
731→                  }
732→                } else {
733→                  updatePayload.executorType = null;
734→                  updatePayload.executorConfig = null;
735→                }
736→                fetch(`/api/collections/${collectionId}`, {
737→                  method: 'PATCH',
738→                  headers: { 'Content-Type': 'application/json' },
739→                  body: JSON.stringify(updatePayload),
740→                });
741→              }}
742→              disabled={isUpdating}
743→            />
744→          </div>
