  const maxPkgLen = 64 - sanitizedTool.length - 2; // 2 for '--'
  if (maxPkgLen > 10) {
    return `${sanitizedPkg.slice(0, maxPkgLen)}--${sanitizedTool}`;
  }

  // Last resort: truncate both
  return fullName.slice(0, 64);
}

