  2→import { forwardRef, useEffect, useId, useRef } from 'react';
  3→import type { CheckboxProps } from './types';
  4→import { checkboxLabelVariants, checkboxUIVariants, checkboxVariants } from './variants';
  5→
  6→/**
  7→ * Checkbox component
  8→ *
  9→ * A custom-styled checkbox with support for indeterminate state,
 10→ * different sizes, states, and optional labels.
 11→ *
 12→ * @example
 13→ * ```tsx
 14→ * import { Checkbox } from '@tpmjs/ui/Checkbox/Checkbox';
 15→ *
 16→ * function MyComponent() {
 17→ *   return (
 18→ *     <Checkbox
 19→ *       label="Accept terms and conditions"
 20→ *       state="default"
 21→ *       size="md"
 22→ *     />
 23→ *   );
 24→ * }
 25→ * ```
 26→ *
 27→ * @example
 28→ * ```tsx
 29→ * // Indeterminate state (for partial selections)
 30→ * <Checkbox
 31→ *   label="Select all"
 32→ *   indeterminate={true}
 33→ *   onChange={handleSelectAll}
 34→ * />
 35→ * ```
 36→ */
 37→export const Checkbox = forwardRef<HTMLInputElement, CheckboxProps>(
 38→  (
 39→    {
 40→      className,
 41→      state = 'default',
 42→      size = 'md',
 43→      indeterminate = false,
 44→      label,
 45→      labelPosition = 'right',
 46→      disabled = false,
 47→      id,
 48→      ...props
 49→    },
 50→    ref
 51→  ) => {
 52→    const inputRef = useRef<HTMLInputElement | null>(null);
 53→
 54→    // Handle indeterminate state via DOM property
 55→    useEffect(() => {
 56→      const input = inputRef.current;
 57→      if (input) {
 58→        input.indeterminate = indeterminate;
 59→        // Set data attribute for CSS styling
 60→        if (indeterminate) {
 61→          input.setAttribute('data-indeterminate', 'true');
 62→        } else {
 63→          input.removeAttribute('data-indeterminate');
 64→        }
 65→      }
 66→    }, [indeterminate]);
 67→
 68→    // Generate unique ID if not provided
 69→    const generatedId = useId();
 70→    const checkboxId = id || `checkbox-${generatedId}`;
 71→
 72→    const checkboxInput = (
 73→      <input
 74→        ref={(node) => {
 75→          inputRef.current = node;
 76→          if (typeof ref === 'function') {
 77→            ref(node);
 78→          } else if (ref) {
 79→            ref.current = node;
 80→          }
 81→        }}
 82→        type="checkbox"
 83→        id={checkboxId}
 84→        className={cn(checkboxVariants({ state, size }), className)}
 85→        disabled={disabled}
 86→        aria-checked={indeterminate ? 'mixed' : undefined}
 87→        {...props}
 88→      />
 89→    );
 90→
 91→    // Visual checkbox box (background, border, etc.) - no icons inside
 92→    const checkboxUI = <span className={cn(checkboxUIVariants({ state, size }))} />;
 93→
 94→    const labelElement = label ? (
 95→      <label
 96→        htmlFor={checkboxId}
 97→        className={cn(checkboxLabelVariants({ size }), labelPosition === 'left' ? 'mr-2' : 'ml-2')}
 98→      >
 99→        {label}
100→      </label>
101→    ) : null;
102→
103→    return (
104→      <div className={cn('inline-flex items-center', disabled && 'cursor-not-allowed')}>
105→        {labelPosition === 'left' && labelElement}
106→        <div className="relative inline-flex items-center justify-center">
107→          {checkboxInput}
108→          {checkboxUI}
109→          {/* Checkmark icon - sibling of input so peer-checked works */}
110→          <svg
