import { cn } from '@tpmjs/utils/cn';
import { forwardRef, useEffect, useId, useRef } from 'react';
import type { CheckboxProps } from './types';
import { checkboxLabelVariants, checkboxUIVariants, checkboxVariants } from './variants';

/**
 * Checkbox component
 *
 * A custom-styled checkbox with support for indeterminate state,
 * different sizes, states, and optional labels.
 *
 * @example
 * ```tsx
 * import { Checkbox } from '@tpmjs/ui/Checkbox/Checkbox';
 *
 * function MyComponent() {
 *   return (
 *     <Checkbox
 *       label="Accept terms and conditions"
 *       state="default"
 *       size="md"
 *     />
 *   );
 * }
 * ```
 *
 * @example
 * ```tsx
 * // Indeterminate state (for partial selections)
 * <Checkbox
 *   label="Select all"
 *   indeterminate={true}
 *   onChange={handleSelectAll}
 * />
 * ```
 */
export const Checkbox = forwardRef<HTMLInputElement, CheckboxProps>(
  (
    {
      className,
      state = 'default',
      size = 'md',
      indeterminate = false,
      label,
      labelPosition = 'right',
      disabled = false,
      id,
      ...props
    },
    ref
  ) => {
    const inputRef = useRef<HTMLInputElement | null>(null);

    // Handle indeterminate state via DOM property
    useEffect(() => {
      const input = inputRef.current;
      if (input) {
        input.indeterminate = indeterminate;
        // Set data attribute for CSS styling
        if (indeterminate) {
          input.setAttribute('data-indeterminate', 'true');
        } else {
          input.removeAttribute('data-indeterminate');
        }
      }
    }, [indeterminate]);

    // Generate unique ID if not provided
    const generatedId = useId();
    const checkboxId = id || `checkbox-${generatedId}`;

    const checkboxInput = (
      <input
        ref={(node) => {
          inputRef.current = node;
          if (typeof ref === 'function') {
            ref(node);
          } else if (ref) {
            ref.current = node;
          }
        }}
        type="checkbox"
        id={checkboxId}
        className={cn(checkboxVariants({ state, size }), className)}
        disabled={disabled}
        aria-checked={indeterminate ? 'mixed' : undefined}
        {...props}
      />
    );

    // Visual checkbox box (background, border, etc.) - no icons inside
    const checkboxUI = <span className={cn(checkboxUIVariants({ state, size }))} />;

    const labelElement = label ? (
      <label
        htmlFor={checkboxId}
        className={cn(checkboxLabelVariants({ size }), labelPosition === 'left' ? 'mr-2' : 'ml-2')}
      >
        {label}
      </label>
    ) : null;

    return (
      <div className={cn('inline-flex items-center', disabled && 'cursor-not-allowed')}>
        {labelPosition === 'left' && labelElement}
        <div className="relative inline-flex items-center justify-center">
          {checkboxInput}
          {checkboxUI}
          {/* Checkmark icon - sibling of input so peer-checked works */}
          <svg
            className={cn(
              'pointer-events-none absolute inset-0 opacity-0 scale-0 transition-all duration-200 text-primary-foreground',
              'peer-checked:opacity-100 peer-checked:scale-100',
              size === 'sm' && 'h-4 w-4',
              size === 'md' && 'h-5 w-5',
              size === 'lg' && 'h-6 w-6'
            )}
            viewBox="0 0 16 16"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
            aria-hidden="true"
          >
            <path
              d="M13.5 4.5L6 12L2.5 8.5"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
          {/* Indeterminate line - sibling of input so peer selectors work */}
          <svg
            className={cn(
              'pointer-events-none absolute inset-0 opacity-0 scale-0 transition-all duration-200 text-primary-foreground',
              'peer-data-[indeterminate=true]:opacity-100 peer-data-[indeterminate=true]:scale-100',
              'peer-checked:opacity-0 peer-checked:scale-0',
              size === 'sm' && 'h-4 w-4',
              size === 'md' && 'h-5 w-5',
              size === 'lg' && 'h-6 w-6'
            )}
            viewBox="0 0 16 16"
            fill="none"
            xmlns="http://www.w3.org/2000/svg"
            aria-hidden="true"
          >
            <path d="M4 8H12" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
          </svg>
        </div>
        {labelPosition === 'right' && labelElement}
      </div>
    );
  }
);

Checkbox.displayName = 'Checkbox';

