    setSyncingServerId(serverId);

    try {
      const res = await fetch(`/api/custom-mcp-servers/${serverId}/sync`, {
        method: 'POST',
      });

      const data = await res.json();

      if (data.success) {
        setServers((prev) =>
          prev.map((s) =>
            s.id === serverId
              ? {
                  ...s,
                  status: 'synced',
                  tools: data.data.tools,
                  toolCount: data.data.toolCount,
                  lastSyncAt: data.data.lastSyncAt,
