 32→/**
 33→ * GET /api/tools/[id]/like
 34→ * Check if the current user has liked this tool
 35→ */
 36→export async function GET(
 37→  _request: NextRequest,
 38→  context: RouteContext
 39→): Promise<NextResponse<ApiResponse>> {
 40→  const requestId = crypto.randomUUID();
 41→  const { id } = await context.params;
 42→
 43→  try {
 44→    const session = await auth.api.getSession({
 45→      headers: await headers(),
 46→    });
 47→
 48→    if (!session) {
 49→      return NextResponse.json(
 50→        {
 51→          success: false,
 52→          error: { code: 'UNAUTHORIZED', message: 'Authentication required' },
 53→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
 54→        },
 55→        { status: 401 }
 56→      );
 57→    }
 58→
 59→    const like = await prisma.toolLike.findUnique({
 60→      where: {
 61→        userId_toolId: {
 62→          userId: session.user.id,
 63→          toolId: id,
 64→        },
 65→      },
 66→    });
