 70→      select: { likeCount: true },
 71→    });
 72→
 73→    return NextResponse.json({
 74→      success: true,
 75→      data: {
 76→        liked: !!like,
 77→        likeCount: tool?.likeCount ?? 0,
 78→      },
 79→      meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
 80→    });
