115→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
116→        },
117→        { status: 401 }
118→      );
119→    }
120→
121→    // Check tool exists
122→    const tool = await prisma.tool.findUnique({
123→      where: { id },
124→    });
125→
126→    if (!tool) {
127→      return NextResponse.json(
128→        {
129→          success: false,
130→          error: { code: 'NOT_FOUND', message: 'Tool not found' },
131→          meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
132→        },
133→        { status: 404 }
134→      );
135→    }
136→
137→    // Check if already liked
138→    const existingLike = await prisma.toolLike.findUnique({
139→      where: {
140→        userId_toolId: {
141→          userId: session.user.id,
142→          toolId: id,
143→        },
144→      },
145→    });
146→
