175→      type: 'TOOL_LIKED',
176→      targetName: tool.name,
177→      targetType: 'tool',
178→      toolId: id,
179→    });
180→
181→    return NextResponse.json({
182→      success: true,
183→      data: {
184→        liked: true,
185→        likeCount: updatedTool.likeCount,
186→      },
187→      meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
188→    });
189→  } catch (error) {
190→    console.error('[API Error] POST /api/tools/[id]/like:', error);
191→    return NextResponse.json(
192→      {
193→        success: false,
194→        error: { code: 'INTERNAL_ERROR', message: 'Failed to like tool' },
195→        meta: { version: API_VERSION, timestamp: new Date().toISOString(), requestId },
196→      },
