const { PrismaClient } = require('@prisma/client');
const { auth } = require('./apps/web/src/lib/auth');
const { discoverRemoteTools, callRemoteTool } = require('./apps/web/src/lib/mcp/remote-client');
const { sanitizeCustomToolName, parseToolName, convertCustomToolToMcp } = require('./apps/web/src/lib/mcp/tool-converter');

const prisma = new PrismaClient();

async function main() {
  console.log('==========================================');
  console.log('  FULL INTEGRATION TEST SUITE');
  console.log('==========================================\n');

  let passed = 0;
  let failed = 0;

  function assert(condition, msg) {
    if (!condition) { 
      console.log('  FAIL:', msg); 
      failed++; 
      throw new Error(msg);
    }
    passed++;
  }

  // Setup: Get a test user with a valid session
  const session = await prisma.session.findFirst({
    where: { expiresAt: { gt: new Date() } },
    include: { user: true },
    orderBy: { expiresAt: 'desc' },
  });
  assert(session, 'Should have a valid session');
  const userId = session.userId;
  console.log('Test user:', session.user.email, '(id:', userId, ')\n');

  // ===== SECTION 1: Tool Converter =====
  console.log('--- Section 1: Tool Converter ---');

  const sanitized = sanitizeCustomToolName('srv-abc', 'my-tool');
  assert(sanitized === 'custom--srv-abc--my-tool', 'sanitizeCustomToolName');
  console.log('  [PASS] sanitizeCustomToolName');

  const parsed = parseToolName('custom--srv-abc--my-tool');
  assert(parsed.type === 'custom' && parsed.serverId === 'srv-abc' && parsed.toolName === 'my-tool', 'parseToolName custom');
  console.log('  [PASS] parseToolName (custom)');

  const parsedBridge = parseToolName('bridge--conn1--bridge-tool');
  assert(parsedBridge.type === 'bridge', 'parseToolName bridge not broken');
  console.log('  [PASS] parseToolName (bridge still works)');

  const mcpTool = convertCustomToolToMcp({
    serverId: 'srv1', serverName: 'TestSrv', name: 'tool1',
    description: 'Test tool', inputSchema: { type: 'object', properties: {} }
  });
  assert(mcpTool.name === 'custom--srv1--tool1', 'convertCustomToolToMcp name');
  assert(mcpTool.inputSchema.type === 'object', 'convertCustomToolToMcp schema');
  console.log('  [PASS] convertCustomToolToMcp');

  const mcpToolWithDisplay = convertCustomToolToMcp({
    serverId: 'srv1', serverName: 'TestSrv', name: 'tool1',
    description: 'Test tool', inputSchema: { type: 'object', properties: {} }
  }, 'Renamed Tool');
  assert(mcpToolWithDisplay.description.includes('Renamed Tool'), 'convertCustomToolToMcp with displayName');
  console.log('  [PASS] convertCustomToolToMcp with displayName');

  // ===== SECTION 2: Database CRUD =====
  console.log('\n--- Section 2: Database Operations ---');

  // Create CustomMcpServer
  const server = await prisma.customMcpServer.create({
    data: {
      userId,
      name: 'Integration Test Server',
      url: 'https://test-mcp-' + Date.now() + '.example.com/mcp',
      authType: 'bearer',
      authHeader: 'Authorization',
      authToken: 'test-token-xyz',
      status: 'synced',
      tools: [
        { name: 'read-file', description: 'Read a file', inputSchema: { type: 'object', properties: { path: { type: 'string' } }, required: ['path'] } },
        { name: 'write-file', description: 'Write a file', inputSchema: { type: 'object', properties: { path: { type: 'string' }, content: { type: 'string' } } } },
      ],
      lastSyncAt: new Date(),
    },
  });
  assert(server.id, 'Create CustomMcpServer');
  assert(server.status === 'synced', 'Server status is synced');
  console.log('  [PASS] Create CustomMcpServer:', server.id);

  // Query back
  const queried = await prisma.customMcpServer.findUnique({ where: { id: server.id } });
  assert(queried, 'Query CustomMcpServer');
  assert(Array.isArray(queried.tools) && queried.tools.length === 2, 'Server has 2 cached tools');
  console.log('  [PASS] Query CustomMcpServer with tools');

  // List by user
  const userServers = await prisma.customMcpServer.findMany({ where: { userId } });
  assert(userServers.some(s => s.id === server.id), 'List servers by user');
  console.log('  [PASS] List servers by user');

  // Unique constraint
  try {
    await prisma.customMcpServer.create({
