import {
  sanitizeCustomToolName,
  parseToolName,
  convertCustomToolToMcp,
} from './apps/web/src/lib/mcp/tool-converter';
import crypto from 'crypto';

const prisma = new PrismaClient();

let passed = 0;
let failed = 0;

function assert(condition: unknown, msg: string): asserts condition {
  if (!condition) {
    console.log('  FAIL:', msg);
    failed++;
    throw new Error(msg);
  }
  passed++;
}

async function signCookie(value: string, secret: string): Promise<string> {
  const key = await crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign']
  );
  const sig = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(value));
  return value + '.' + Buffer.from(sig).toString('base64');
}

async function main() {
  console.log('==========================================');
  console.log('  CUSTOM MCP SERVER - INTEGRATION TESTS');
  console.log('==========================================\n');

  // Setup: Get a test user with a valid session
  const session = await prisma.session.findFirst({
    where: { expiresAt: { gt: new Date() } },
