  assert(mcpTool.inputSchema.type === 'object', 'convertCustomToolToMcp schema');
  console.log('  [PASS] convertCustomToolToMcp');

  const mcpToolDisplay = convertCustomToolToMcp(
    {
      serverId: 'srv1',
      serverName: 'TestSrv',
      name: 'tool1',
      description: 'Test tool',
      inputSchema: { type: 'object', properties: {} },
    },
    'Renamed Tool'
  );
  assert(mcpToolDisplay.description.includes('Renamed Tool'), 'convertCustomToolToMcp with displayName');
