  console.log('  [PASS] Create CollectionCustomTool 1:', ct1.id);

  const ct2 = await prisma.collectionCustomTool.create({
    data: {
      collectionId: collection.id,
      serverId: server.id,
      toolName: 'write-file',
    },
  });
  assert(ct2.id, 'Create CollectionCustomTool 2');
  console.log('  [PASS] Create CollectionCustomTool 2');

  // Unique constraint on collection tools
  try {
    await prisma.collectionCustomTool.create({
      data: { collectionId: collection.id, serverId: server.id, toolName: 'read-file' },
    });
    assert(false, 'Should prevent duplicate tool');
  } catch (err: any) {
    assert(err.code === 'P2002', 'Unique constraint [collectionId, serverId, toolName]');
    console.log('  [PASS] Unique constraint [collectionId, serverId, toolName]');
  }

  // Query collection with tools and server
  const collWithTools = await prisma.collection.findUnique({
    where: { id: collection.id },
    include: { customTools: { include: { server: true } } },
  });
  assert(collWithTools, 'Query collection with customTools');
  assert(collWithTools.customTools.length === 2, 'Collection has 2 custom tools');
  assert(
    collWithTools.customTools[0].server.name === 'Integration Test Server',
    'Custom tool includes server'
  );
  console.log('  [PASS] Query collection with customTools + server relation');

  // ===== SECTION 3: MCP Handler Logic Simulation =====
  console.log('\n--- Section 3: MCP Handler Logic ---');

  // Simulate handleToolsList - build custom tools array from DB data
  const customToolsList: ReturnType<typeof convertCustomToolToMcp>[] = [];
