    const srvTools = ct.server.tools as any[];
    const toolDef = srvTools.find((t: any) => t.name === ct.toolName);
    if (!toolDef) continue;
    customToolsList.push(
      convertCustomToolToMcp(
        {
          serverId: ct.serverId,
          serverName: ct.server.name,
          name: ct.toolName,
          description: toolDef.description,
          inputSchema: toolDef.inputSchema,
        },
        ct.displayName ?? undefined
      )
    );
  }
  assert(customToolsList.length === 2, 'handleToolsList builds 2 custom tools');
