  assert(customToolsList[0].inputSchema.type === 'object', 'Custom tool has schema');
  console.log('  [PASS] handleToolsList builds custom tools correctly');
  console.log('    Tool 0:', customToolsList[0].name, '-', customToolsList[0].description);
  console.log('    Tool 1:', customToolsList[1].name, '-', customToolsList[1].description);

