    assert(false, 'Should throw on bad URL');
  } catch (err: any) {
    assert(err.message, 'discoverRemoteTools throws on connection failure');
    console.log('  [PASS] discoverRemoteTools fails gracefully:', err.message.substring(0, 60));
  }

  try {
    await callRemoteTool({ url: 'http://localhost:19999/fake' }, 'test', {});
    assert(false, 'Should throw on bad URL');
  } catch (err: any) {
    assert(err.message, 'callRemoteTool throws on connection failure');
    console.log('  [PASS] callRemoteTool fails gracefully:', err.message.substring(0, 60));
  }

  // ===== SECTION 5: Auth Integration =====
  console.log('\n--- Section 5: Auth (via better-auth directly) ---');

  const secret = process.env.BETTER_AUTH_SECRET;
  assert(secret, 'BETTER_AUTH_SECRET is set');

  const signedToken = await signCookie(session.token, secret);
  const reqHeaders = new Headers();
  reqHeaders.set('cookie', 'better-auth.session_token=' + signedToken);

  const authResult = await auth.api.getSession({ headers: reqHeaders });
  assert(authResult, 'getSession returns session');
  assert(authResult.user.id === userId, 'getSession returns correct user');
  console.log('  [PASS] auth.api.getSession works with signed cookie');

