  assert(toolCountBefore === 2, 'Have 2 tools before delete');

  await prisma.customMcpServer.delete({ where: { id: server.id } });

  const toolCountAfter = await prisma.collectionCustomTool.count({
    where: { collectionId: collection.id },
  });
  assert(toolCountAfter === 0, 'Cascade delete removed all custom tools');
  console.log('  [PASS] Cascade delete: server deletion removes custom tools');

  const deletedServer = await prisma.customMcpServer.findUnique({ where: { id: server.id } });
  assert(!deletedServer, 'Server is deleted');
  console.log('  [PASS] Server is fully deleted');

  // Cleanup
  await prisma.collection.delete({ where: { id: collection.id } });
  console.log('  [PASS] Cleaned up test data');

  // ===== SUMMARY =====
  console.log('\n==========================================');
  console.log(`  RESULTS: ${passed} passed, ${failed} failed`);
  console.log('==========================================');

  if (failed > 0) process.exit(1);
}

main()
  .catch((err) => {
    console.error('\nFATAL:', err.message);
    process.exit(1);
